    if (!today || today.trim() === "") {
      throw new Error("本日の予定は必須項目です");
    }
  
    // Check today plan length
    if (today && today.length > MAX_PLAN_LENGTH) {
      throw new Error("今日やること形式が不正です");
    }
  
