    if (today && /[\x00-\x1F]/.test(today)) {
      throw new Error("今日やること形式が不正です");
    }
  
    // Validate challenge field
    if (!challenge || challenge.trim() === "") {
      errors.push({
        field: "current_issue",
        message: "抱えている課題は必須項目です",
      });
      validationErrors.current_issue = "抱えている課題は必須項目です";
    }
  
